#ifndef CPP_BASICS_INVENTORY_HPP
#define CPP_BASICS_INVENTORY_HPP
#include <istream>
#include <ostream>
#include <string>
#include <vector>

namespace study {

// 필드별 값을 저장한다. string 객체의 메모리 표현을 그대로 저장하지 않는다.
struct Item {
    int id{};
    std::string name;
    int quantity{};
};
using Inventory = std::vector<Item>;

// 유효하지 않은 데이터와 검사한 스트림 실패는 runtime_error로 알린다.
// 메모리 할당 등 표준 라이브러리 연산에서 생기는 다른 예외까지 제한하는 선언은 아니다.
void Save(std::ostream& output, const Inventory& items);
// 전부 읽고 검증한 새 결과만 반환한다. 호출자의 기존 Inventory를 변경하지 않는다.
Inventory Load(std::istream& input);

}
#endif

#include "inventory.hpp"
#include <iomanip>
#include <set>
#include <sstream>
#include <stdexcept>

namespace study {
namespace {

// 이 번역 단위에서만 쓰는 검사다. 저장 전과 완전히 읽은 뒤에 같은 계약을 적용한다.
void Validate(const Inventory& items) {
    if (items.size() > 1000) throw std::runtime_error("too many items");
    std::set<int> ids;
    for (const auto& item : items) {
        if (item.id <= 0 || !ids.insert(item.id).second) throw std::runtime_error("invalid/duplicate id");
        if (item.quantity < 0 || item.quantity > 1000000) throw std::runtime_error("quantity range");
        // name.size()는 char 원소 수다. UTF-8 표시 글자 수나 인코딩 유효성 검사가 아니다.
        if (item.name.empty() || item.name.size() > 256 || item.name.find_first_of("\r\n") != std::string::npos)
            throw std::runtime_error("invalid name");
    }
}

void RequireEnd(std::istream& line) {
    // 필드를 읽고 남은 공백은 허용하지만 다른 토큰은 거부한다.
    line >> std::ws;
    if (!line.eof()) throw std::runtime_error("trailing data");
}

}

void Save(std::ostream& output, const Inventory& items) {
    // 데이터 오류로 일부만 기록하는 일을 피하려고 먼저 전체 값을 검사한다.
    Validate(items);
    output << "INV1 " << items.size() << '\n';
    for (const auto& item : items)
        output << item.id << ' ' << std::quoted(item.name) << ' ' << item.quantity << '\n';
    // 여기까지의 스트림 상태를 확인한다. 이후 close, 원자적 교체, 내구성은 별도다.
    if (!output) throw std::runtime_error("write failed");
}

Inventory Load(std::istream& input) {
    std::string line;
    if (!std::getline(input, line)) throw std::runtime_error("missing header");
    std::istringstream header{line};
    std::string magic;
    long long count{};
    // 개수 상한을 먼저 확인하고 나서 저장 공간을 예약한다.
    if (!(header >> magic >> count) || magic != "INV1" || count < 0 || count > 1000)
        throw std::runtime_error("bad header");
    RequireEnd(header);

    Inventory items;
    items.reserve(static_cast<std::size_t>(count));
    for (long long i = 0; i < count; ++i) {
        if (!std::getline(input, line)) throw std::runtime_error("truncated file");
        std::istringstream row{line};
        Item item;
        // quoted는 따옴표 문자열 외에 공백 없는 비인용 토큰도 받아들인다.
        if (!(row >> item.id >> std::quoted(item.name) >> item.quantity)) throw std::runtime_error("bad row");
        RequireEnd(row);
        items.push_back(std::move(item));
    }

    // 명시한 개수 뒤에는 빈 줄이나 지정한 공백 문자만 허용한다.
    while (std::getline(input, line)) {
        if (line.find_first_not_of(" \t\r") != std::string::npos) throw std::runtime_error("extra row");
    }
    // 정상적인 EOF와 실제 스트림 오류를 구별한다.
    if (input.bad() || (input.fail() && !input.eof())) throw std::runtime_error("read failed");
    // 행을 전부 읽은 뒤 ID 중복·필드 범위를 검사하고 완성된 결과만 반환한다.
    Validate(items);
    return items;
}

}

#include "check.hpp"
#include "inventory.hpp"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <stdexcept>
#include <system_error>

namespace fs = std::filesystem;

// 테스트 전용 임시 디렉터리의 소유자다. 기존 사용자 파일을 대상으로 삼지 않는다.
class TempDirectory {
public:
    TempDirectory() {
        const auto token = std::chrono::steady_clock::now().time_since_epoch().count();
        for (int i = 0; i < 100; ++i) {
            auto candidate = fs::temp_directory_path() / ("cpp_basics_" + std::to_string(token) + "_" + std::to_string(i));
            if (fs::create_directory(candidate)) {
                path = std::move(candidate);
                return;
            }
        }
        throw std::runtime_error("cannot create temporary directory");
    }
    TempDirectory(const TempDirectory&) = delete;
    TempDirectory& operator=(const TempDirectory&) = delete;
    // 소멸자에서 예외를 던지지 않는 정리 방식이다. 정리 오류는 이 학습 예제에서 보고하지 않는다.
    ~TempDirectory() {
        std::error_code error;
        fs::remove_all(path, error);
    }
    fs::path path;
};

// 잘못된 입력이 Load의 runtime_error로 거부되는지 확인한다.
bool Rejects(const std::string& text) {
    try {
        std::istringstream input{text};
        (void)study::Load(input);
    }
    catch (const std::runtime_error&) { return true; }
    return false;
}

int main() {
    try {
        study::Inventory items{{1,"Health Potion",3},{2,"Mana",1}};
        std::ostringstream text;
        study::Save(text, items);
        std::istringstream input{text.str()};
        const auto loaded = study::Load(input);
        // 메모리 스트림의 저장 → 로드로 주요 필드가 돌아오는지 확인한다.
        CHECK(loaded.size() == 2);
        CHECK(loaded.at(0).name == "Health Potion");
        CHECK(loaded.at(0).quantity == 3);

        // 헤더·개수·누락 행·필드·중복·잔여 데이터가 잘못된 경우를 각각 기록한다.
        CHECK(Rejects(""));
        CHECK(Rejects("INV2 0\n"));
        CHECK(Rejects("INV1 -1\n"));
        CHECK(Rejects("INV1 1001\n"));
        CHECK(Rejects("INV1 2\n1 \"A\" 1\n"));
        CHECK(Rejects("INV1 1\n1 \"A\" -1\n"));
        CHECK(Rejects("INV1 2\n1 \"A\" 1\n1 \"B\" 2\n"));
        CHECK(Rejects("INV1 1\n1 \"A\" 1 junk\n"));
        CHECK(Rejects("INV1 0\nextra\n"));
        CHECK(Rejects("INV1 1\n1 \"\" 0\n"));

        std::istringstream empty{"INV1 0\n"};
        CHECK(study::Load(empty).empty());
        bool rejected = false;
        try {
            std::ostringstream out;
            study::Save(out, {{1,"A",-1}});
        }
        catch (const std::runtime_error&) { rejected = true; }
        CHECK(rejected);

        TempDirectory temp;
        const auto file = temp.path / "inventory.txt";
        {
            // binary는 스트림의 모드다. INV1의 필드 기반 텍스트 형식을 바꾸지 않는다.
            std::ofstream out{file, std::ios::binary};
            if(!out) throw std::runtime_error("open failed");
            study::Save(out, items);
            out.close();
            // close에서 지연된 쓰기 실패가 생길 수 있으므로 종료 상태도 확인한다.
            if(!out) throw std::runtime_error("close failed");
        }
        {
            std::ifstream in{file, std::ios::binary};
            if(!in) throw std::runtime_error("open failed");
            CHECK(study::Load(in).size() == 2);
        }
        const auto copied = temp.path / "copy.bin";
        CHECK(fs::copy_file(file, copied));
        // 이 CHECK는 파일 크기 일치만 검사한다. 바이트별 내용 비교는 아니다.
        CHECK(fs::file_size(copied) == fs::file_size(file));
        {
            std::ifstream missing{temp.path / "missing.txt"};
            CHECK(!missing);
        }
        // 상대 경로의 기준은 프로세스의 현재 작업 디렉터리다.
        std::cout << "cwd=" << fs::current_path().string() << '\n';
        Report();
    }
    catch(const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}
